INSERT INTO `wp_options` VALUES (675,'_site_transient_feed_b85365aa61afaf3d4189819a6f57c4c4','a:6:{s:5:\"child\";a:1:{s:0:\"\";a:1:{s:3:\"rss\";a:1:{i:0;a:6:{s:4:\"data\";s:3:\"\n\n\n\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:7:\"version\";s:3:\"2.0\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:0:\"\";a:1:{s:7:\"channel\";a:1:{i:0;a:6:{s:4:\"data\";s:52:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\n \n	\n		\n		\n		\n		\n		\n		\n		\n		\n		\n	\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:8:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:29:\"Blog – WordPress.org Brasil\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:24:\"https://br.wordpress.org\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:0:\"\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:13:\"lastBuildDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 15 Sep 2026 16:30:01 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"language\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"pt-BR\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:9:\"generator\";a:1:{i:0;a:5:{s:4:\"data\";s:40:\"https://wordpress.org/?v=7.2-alpha-63646\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"image\";a:1:{i:0;a:6:{s:4:\"data\";s:11:\"\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:0:\"\";a:5:{s:3:\"url\";a:1:{i:0;a:5:{s:4:\"data\";s:29:\"https://s.w.org/favicon.ico?2\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:29:\"Blog – WordPress.org Brasil\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:24:\"https://br.wordpress.org\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"width\";a:1:{i:0;a:5:{s:4:\"data\";s:2:\"32\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:6:\"height\";a:1:{i:0;a:5:{s:4:\"data\";s:2:\"32\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}s:4:\"item\";a:10:{i:0;a:6:{s:4:\"data\";s:73:\"\n		\n		\n					\n		\n		\n		\n				\n		\n\n					\n										\n					\n					\n			\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:6:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:44:\"Novidades no AI 1.3.0 (18 de agosto de 2026)\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:79:\"https://br.wordpress.org/2026/09/16/novidades-no-ai-1-3-0-18-de-agosto-de-2026/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:87:\"https://br.wordpress.org/2026/09/16/novidades-no-ai-1-3-0-18-de-agosto-de-2026/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 16 Sep 2026 11:29:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"Lançamentos\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://br.wordpress.org/?p=3707\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:349:\"O AI 1.3.0 foi lançado e já está disponível para baixar! Os posts da série “Novidades no AI…” (identificados com a tag #ai-release) são publicados após cada lançamento do plugin AI e apresentam os novos recursos incluídos em cada versão. Temos o prazer de anunciar o lançamento do AI 1.3.0, a atualização mais recente do [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Fellyph Cintra\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:22247:\"\n<p class=\"wp-block-paragraph\">O <strong>AI 1.3.0</strong> foi lançado e <a href=\"https://wordpress.org/plugins/ai/\">já está disponível para baixar</a>! Os posts da série “Novidades no AI…” (identificados com a tag <code><a href=\"https://make.wordpress.org/ai/tag/ai-release/\">#ai-release</a></code>) são publicados após cada lançamento do plugin AI e apresentam os novos recursos incluídos em cada versão.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Temos o prazer de anunciar o lançamento do <strong><a href=\"https://github.com/WordPress/ai/releases/tag/1.3.0\">AI 1.3.0</a></strong>, a atualização mais recente do plugin canônico que viabiliza recursos de IA no WordPress. Esta versão adiciona novos fluxos de trabalho no editor para tradução de conteúdo e geração de slugs, apresenta controles específicos para expor habilidades personalizadas e amplia as ferramentas do plugin para desenvolvedores. Ela também reforça a segurança, melhora a acessibilidade e corrige vários experimentos existentes.</p>\n\n\n\n<h2 class=\"wp-block-heading\">O que há de novo na versão 1.3.0?</h2>\n\n\n\n<h3 class=\"wp-block-heading\">Novo experimento do editor: tradução de conteúdo</h3>\n\n\n\n<p class=\"wp-block-paragraph\">O novo experimento <strong>Tradução de conteúdo</strong> permite que editores traduzam conteúdo sem sair do editor de posts.</p>\n\n\n\n		<figure class=\"wp-block-jetpack-videopress jetpack-videopress-player\" style=\"\" >\n			<div class=\"jetpack-videopress-player__wrapper\"> <iframe title=\"VideoPress Video Player\" aria-label=\"VideoPress Video Player\" width=\"500\" height=\"358\" src=\"https://videopress.com/embed/s9tvqRwq?cover=1&amp;autoPlay=0&amp;controls=1&amp;loop=0&amp;muted=0&amp;persistVolume=1&amp;playsinline=0&amp;preloadContent=metadata&amp;useAverageColor=1&amp;hd=0\" frameborder=\"0\" allowfullscreen data-resize-to-parent=\"true\" allow=\"clipboard-write; presentation\"></iframe><script src=\'https://v0.wordpress.com/js/next/videopress-iframe.js?m=1770107250\'></script></div>\n			\n			\n		</figure>\n		\n\n\n<p class=\"wp-block-paragraph\">Depois que um idioma de destino é selecionado, o experimento traduz os blocos Parágrafo e Título compatíveis. Editores também podem optar por traduzir o título do post. O conteúdo traduzido substitui o conteúdo original no editor, onde pode ser revisado e ajustado antes da publicação.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Novo experimento do editor: geração de slugs</h3>\n\n\n\n<p class=\"wp-block-paragraph\">A geração de slugs sugere links permanentes, concisos e adequados para mecanismos de busca, com base no título e no conteúdo do post.</p>\n\n\n\n		<figure class=\"wp-block-jetpack-videopress jetpack-videopress-player\" style=\"\" >\n			<div class=\"jetpack-videopress-player__wrapper\"> <iframe title=\"VideoPress Video Player\" aria-label=\"VideoPress Video Player\" width=\"500\" height=\"395\" src=\"https://videopress.com/embed/hJcLMGp9?cover=1&amp;autoPlay=0&amp;controls=1&amp;loop=0&amp;muted=0&amp;persistVolume=1&amp;playsinline=0&amp;preloadContent=metadata&amp;useAverageColor=1&amp;hd=0\" frameborder=\"0\" allowfullscreen data-resize-to-parent=\"true\" allow=\"clipboard-write; presentation\"></iframe><script src=\'https://v0.wordpress.com/js/next/videopress-iframe.js?m=1770107250\'></script></div>\n			\n			\n		</figure>\n		\n\n\n<p class=\"wp-block-paragraph\">As sugestões ficam disponíveis nos controles de link permanente e durante o fluxo de pré-publicação. Antes de publicar, editores podem revisar, editar, gerar novamente e aplicar um slug sugerido. A interface também mostra uma prévia de como o texto editado manualmente será normalizado e impede a aplicação de valores que não gerem um slug válido.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Novo experimento administrativo: habilidades personalizadas</h3>\n\n\n\n<p class=\"wp-block-paragraph\">A versão 1.3.0 apresenta uma única configuração opcional para expor as habilidades personalizadas do WordPress oferecidas pelo plugin por meio da Abilities API.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Ativar o experimento <strong>Habilidades personalizadas</strong> registra as seguintes habilidades:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><code>ai/get-post-details</code></li>\n\n\n\n<li><code>ai/get-post-terms</code></li>\n\n\n\n<li><code>core/read-settings</code></li>\n\n\n\n<li><code>core/read-users</code></li>\n\n\n\n<li><code>core/read-content</code></li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">Essas habilidades não são mais registradas automaticamente. Depois da atualização, sites ou integrações que já as utilizam precisam ativar <strong>Habilidades personalizadas</strong> em <strong>Configurações &gt; AI &gt; Experimentos administrativos</strong>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Os recursos internos do plugin AI continuam funcionando, independentemente de o experimento estar ativado. O controle determina a exposição externa por meio de interfaces como a Abilities API e o Model Context Protocol (MCP).</p>\n\n\n\n<h3 class=\"wp-block-heading\">Nova ferramenta para desenvolvedores: importação e exportação de configurações</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Agora, administradores podem exportar as configurações não confidenciais do plugin AI para um arquivo JSON e importá-las em outro site.</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><a href=\"https://br.wordpress.org/files/2026/09/export-import-settings.png\"><img fetchpriority=\"high\" decoding=\"async\" width=\"984\" height=\"568\" src=\"https://br.wordpress.org/files/2026/09/export-import-settings.png\" alt=\"\" class=\"wp-image-3719\" srcset=\"https://br.wordpress.org/files/2026/09/export-import-settings.png 984w, https://br.wordpress.org/files/2026/09/export-import-settings-300x173.png 300w, https://br.wordpress.org/files/2026/09/export-import-settings-767x443.png 767w\" sizes=\"(max-width: 984px) 100vw, 984px\" /></a></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Isso facilita a transferência das configurações de experimentos e de desenvolvimento entre ambientes locais, de homologação e de produção. Credenciais, chaves de API, tokens e outros valores confidenciais não são incluídos nas exportações nem substituídos durante a importação.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Os controles de importação e exportação estão disponíveis no menu da tela de configurações de AI.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A versão também adiciona uma seção <strong>Plugin AI</strong> à tela Saúde do site. Ela inclui informações de configuração e testes de status que podem ajudar administradores a identificar problemas de configuração ou conectividade.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Melhorias na classificação de conteúdo</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Agora, a <strong>Classificação de conteúdo</strong> gera sugestões mais relevantes de categorias e tags. Para isso, ela fornece ao modelo um contexto melhor sobre a taxonomia, diferencia categorias abrangentes de tags específicas e remove resultados com baixo nível de confiança.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A atualização também apresenta três filtros para sites que precisam de mais controle sobre a classificação:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><code>wpai_content_classification_available_terms</code></li>\n\n\n\n<li><code>wpai_content_classification_min_confidence</code></li>\n\n\n\n<li><code>wpai_content_classification_candidate_pool_size</code></li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">Esses filtros podem ser usados para personalizar os termos-candidato fornecidos ao modelo, ajustar o nível mínimo de confiança exigido para uma sugestão e controlar o tamanho do conjunto de candidatos.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Novos pontos de extensão para desenvolvedores</h3>\n\n\n\n<p class=\"wp-block-paragraph\">A versão 1.3.0 adiciona filtros específicos para cada habilidade. Eles permitem personalizar instruções de sistema, prompts montados e construtores de prompts sem precisar criar uma bifurcação do plugin.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Esses pontos de extensão permitem que desenvolvedores modifiquem prompts, preferências de provedor ou modelo, opções de solicitação e outros comportamentos específicos de cada habilidade, preservando a implementação padrão do plugin.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A versão também adiciona:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Uma API pública <code>WordPress\\AI\\log_ai_request()</code>, que permite que servidores MCP e consumidores diretos de habilidades registrem atividades no Registro de solicitações de IA.</li>\n\n\n\n<li>Compatibilidade com provedores personalizados no filtro de provedores do Explorador de habilidades.</li>\n\n\n\n<li>Estatísticas do Explorador de habilidades baseadas na origem, garantindo que as habilidades de provedores personalizados continuem aparecendo nas categorias Núcleo, Plugin ou Tema correspondentes.</li>\n\n\n\n<li>Código de geração de embeddings do PHP AI Client como base para ambientes compatíveis com embeddings.</li>\n\n\n\n<li>Ordenação alfabética pelo nome de exibição das coleções retornadas por <code>core/read-users</code>.</li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\">Melhorias de segurança</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Esta versão inclui várias mudanças para reforçar a forma como o plugin processa conteúdo gerado, operações em massa e URLs de imagens fornecidas externamente.</p>\n\n\n\n<p class=\"wp-block-paragraph\">As atualizações incluem:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Sanitização adicional do conteúdo enviado a um modelo de linguagem de grande porte ou renderizado a partir dele.</li>\n\n\n\n<li>Verificação de nonce antes da geração em massa de textos alternativos e sínteses.</li>\n\n\n\n<li>Validação para garantir que URLs de imagens personalizadas sejam públicas, usem um tipo de imagem permitido e não redirecionem para outro local não verificado.</li>\n\n\n\n<li>Limites para downloads de imagens personalizadas, incluindo tipos MIME, tempos limite e tamanhos máximos de arquivo configuráveis.</li>\n\n\n\n<li>Um novo filtro <code>wpai_bulk_action_max_items</code> para controlar o número de itens processados em uma única solicitação em massa.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">Recomendamos que os sites que usam o plugin AI façam a atualização o quanto antes.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Melhorias de acessibilidade e fluxo de trabalho</h3>\n\n\n\n<p class=\"wp-block-paragraph\">O AI 1.3.0 inclui várias melhorias na navegação pelo teclado, no gerenciamento de foco e no retorno fornecido pelo editor:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Agora, o foco se move de forma previsível ao gerar, aceitar ou dispensar sugestões da Classificação de conteúdo.</li>\n\n\n\n<li>Os campos de título e resposta gerados recebem foco quando o conteúdo está pronto.</li>\n\n\n\n<li>O menu de tom do recurso Sugerir resposta pode ser fechado com a tecla Esc e restaura o foco corretamente.</li>\n\n\n\n<li>Os detalhes do provedor e do modelo no Registro de solicitações de IA estão mais acessíveis para quem usa teclado ou tecnologia assistiva.</li>\n\n\n\n<li>Os controles de resumo e síntese agora compartilham o estado de geração entre várias interfaces do editor, evitando solicitações duplicadas.</li>\n\n\n\n<li>A lista de experimentos foi reorganizada: os experimentos administrativos relacionados foram agrupados, enquanto os experimentos do editor foram ordenados alfabeticamente.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">A versão também corrige vários problemas de fluxo de trabalho:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>O redimensionamento de conteúdo preserva links, ênfase, código em linha e outros elementos HTML em linha.</li>\n\n\n\n<li>As atualizações editoriais são compatíveis com o bloco Citação destacada e outros blocos que armazenam texto em um atributo <code>value</code>.</li>\n\n\n\n<li>As atualizações editoriais incluem links para as revisões visuais do WordPress, quando disponíveis.</li>\n\n\n\n<li>As metadescrições aplicadas a páginas e tipos de post personalizados são preservadas quando o Yoast SEO está ativo.</li>\n\n\n\n<li>Ações em massa concluídas não são mais executadas quando uma lista é ordenada ou paginada.</li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\">Observações sobre a atualização</h3>\n\n\n\n<h4 class=\"wp-block-heading\">As habilidades personalizadas precisam ser ativadas</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Depois da atualização, as integrações que usam <code>ai/get-post-details</code>, <code>ai/get-post-terms</code>, <code>core/read-settings</code>, <code>core/read-users</code> ou <code>core/read-content</code> precisam ativar o novo experimento <strong>Habilidades personalizadas</strong>.</p>\n\n\n\n<h4 class=\"wp-block-heading\">As chaves de metadados de post agora usam o prefixo <code>wpai_</code></h4>\n\n\n\n<p class=\"wp-block-paragraph\">As seguintes chaves de metadados foram renomeadas:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><code>ai_generated</code> para <code>wpai_generated</code></li>\n\n\n\n<li><code>ai_generated_summary</code> para <code>wpai_generated_summary</code></li>\n\n\n\n<li><code>ai_note</code> para <code>wpai_note</code></li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">O plugin migra os próprios dados armazenados, mas códigos de terceiros que referenciam essas chaves diretamente precisam ser atualizados.</p>\n\n\n\n<h4 class=\"wp-block-heading\">APIs públicas foram descontinuadas</h4>\n\n\n\n<p class=\"wp-block-paragraph\">A classe <code>AI_Service</code> e a função auxiliar <code>get_ai_service()</code> foram descontinuadas e serão removidas na próxima versão principal. Desenvolvedores devem usar <code>wp_ai_client_prompt()</code> diretamente.</p>\n\n\n\n<p class=\"wp-block-paragraph\">O filtro não utilizado <code>wpai_meta_description_result_temperature</code> também foi descontinuado e está programado para ser removido na próxima versão.</p>\n\n\n\n<h4 class=\"wp-block-heading\">Os dados do plugin são removidos quando ele é excluído</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Agora, excluir o plugin AI remove suas configurações, transientes, eventos agendados e a tabela do registro de solicitações. Desativar o plugin não remove esses dados.</p>\n\n\n\n<h4 class=\"wp-block-heading\">Outras atualizações</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Os modelos preferenciais dos três provedores padrão foram substituídos por modelos mais recentes. O plugin também não define mais valores personalizados de temperatura em suas solicitações, o que melhora a compatibilidade com modelos que não aceitam esses parâmetros.</p>\n\n\n\n<p class=\"wp-block-paragraph\">O AI 1.3.0 foi testado com o WordPress 7.1 e inclui pacotes do WordPress, ferramentas de desenvolvimento, dependências de teste e GitHub Actions atualizados.</p>\n\n\n\n<h2 class=\"wp-block-heading\">O que vem a seguir?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">O trabalho em outros recursos, experimentos e melhorias de infraestrutura planejados para a versão <a href=\"https://github.com/WordPress/ai/milestone/23\">1.4.0 </a>e versões futuras já está em andamento. Entre eles estão:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Novo experimento: <a href=\"https://github.com/WordPress/ai/pull/887\">Sugestões de links internos</a></li>\n\n\n\n<li>Novo experimento: <a href=\"https://github.com/WordPress/ai/pull/888\">Texto para fala</a></li>\n\n\n\n<li>Novo experimento: <a href=\"https://github.com/WordPress/ai/issues/325\">Integração com o Editor de mídia experimental do Gutenberg</a>, incluindo <a href=\"https://github.com/WordPress/ai/issues/238\">sugestões de corte com reconhecimento de foco</a></li>\n\n\n\n<li>Novo experimento: <a href=\"https://github.com/WordPress/ai/issues/27\">Conectores de provedores de IA em destaque</a></li>\n\n\n\n<li>Novo experimento: <a href=\"https://github.com/WordPress/ai/pull/855\">Feeds Markdown</a></li>\n\n\n\n<li>Novo experimento: Busca vetorial nativa [1, 2]</li>\n\n\n\n<li>Novo experimento: Rastreamento da procedência de conteúdo em <a href=\"https://github.com/WordPress/ai/pull/294\">textos</a> e <a href=\"https://github.com/WordPress/ai/pull/302\">imagens</a> por meio da <a href=\"https://c2pa.org/\">C2PA</a>, além da <a href=\"https://github.com/WordPress/ai/issues/421\">detecção de manifestos C2PA durante o envio</a></li>\n\n\n\n<li>Experimento atualizado: <a href=\"https://github.com/WordPress/ai/issues/324\">Integração do Refine from Notes com a colaboração em tempo real</a></li>\n\n\n\n<li>Experimento atualizado: <a href=\"https://github.com/WordPress/ai/pull/681\">Adição de uma pontuação de valor aos comentários</a></li>\n\n\n\n<li>Nova ferramenta para desenvolvedores: <a href=\"https://github.com/WordPress/ai/pull/749\">Controles de acesso por função e usuário</a></li>\n\n\n\n<li>Novas habilidades: <code>core/read-nav-menus</code>, <code>core/manage-settings</code> e <code>core/edit-content</code></li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">Esses conceitos ainda estão em fase experimental, mas ajudam a testar como a IA pode oferecer suporte a fluxos de trabalho reais em todo o WordPress.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Agradecimentos às pessoas que contribuíram</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Agradecemos muito a todas as pessoas que contribuíram para esta versão, incluindo:</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\'https://profiles.wordpress.org/dkotter/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>dkotter</a>, <a href=\'https://profiles.wordpress.org/jeffpaul/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>jeffpaul</a>, <a href=\'https://profiles.wordpress.org/yogeshbhutkar/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>yogeshbhutkar</a>, <a href=\'https://profiles.wordpress.org/milindmore22/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>milindmore22</a>, <a href=\'https://profiles.wordpress.org/ekamran/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>ekamran</a>, <a href=\'https://profiles.wordpress.org/hbhalodia/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>hbhalodia</a>, <a href=\'https://profiles.wordpress.org/gautam23/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>gautam23</a>, <a href=\'https://profiles.wordpress.org/alkesh7/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>alkesh7</a>, <a href=\'https://profiles.wordpress.org/gajendrasingh/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>gajendrasingh</a>, <a href=\'https://profiles.wordpress.org/laurisaarni/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>laurisaarni</a>, <a href=\'https://profiles.wordpress.org/mikinc860/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>mikinc860</a>, <a href=\'https://profiles.wordpress.org/justlevine/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>justlevine</a>, <a href=\'https://profiles.wordpress.org/thehercules/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>thehercules</a>, <a href=\'https://profiles.wordpress.org/hasanazizul/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>hasanazizul</a>, <a href=\'https://profiles.wordpress.org/n1schay/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>n1schay</a>, <a href=\'https://profiles.wordpress.org/malaytiwari/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>malaytiwari</a>, <a href=\'https://profiles.wordpress.org/ankitkumarshah/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>ankitkumarshah</a>, <a href=\'https://profiles.wordpress.org/gziolo/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>gziolo</a>, <a href=\'https://profiles.wordpress.org/jorgefilipecosta/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>jorgefilipecosta</a>, <a href=\'https://profiles.wordpress.org/theaminuldev/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>theaminuldev</a>, <a href=\'https://profiles.wordpress.org/anubhav24/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>anubhav24</a>, @carlos-widgilabs, <a href=\'https://profiles.wordpress.org/fahimmurshed/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>fahimmurshed</a>, @trap-bytes e outras pessoas envolvidas na revisão, nos testes, nas traduções e nos <a href=\"https://github.com/WordPress/ai/compare/1.2.0...1.3.0\">59 commits em 203 arquivos entre as versões 1.2.0 e 1.3.0</a>. A ajuda e o retorno de vocês tornam possíveis esses recursos e experimentos.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Também agradecemos às pessoas que contribuíram com traduções para as <a href=\"https://translate.wordpress.org/projects/wp-plugins/ai/\">localidades tcheca, inglesa (Reino Unido), dinamarquesa, alemã, alemã (formal), japonesa, coreana, persa, polonesa, portuguesa (Brasil), russa, espanhola (Argentina), espanhola (Chile), espanhola (Espanha), turca e vietnamita</a>, garantindo que os pacotes de idioma estejam disponíveis. <a href=\"https://translate.wordpress.org/projects/wp-plugins/ai/\">Traduzir o plugin AI </a>é uma ótima forma de contribuir, e a participação de mais pessoas nesse trabalho será muito bem-vinda e valorizada!</p>\n\n\n\n<h2 class=\"wp-block-heading\">Participe</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Como sempre, comentários, testes e contribuições da comunidade são bem-vindos. Se você tem interesse na experiência de uso do editor, em APIs, acessibilidade, desempenho ou ética e políticas de IA, há muitas maneiras de participar.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Você já pode <a href=\"https://wordpress.org/plugins/ai/?preview=1\">explorar a versão 1.3.0</a>, revisar <a href=\"https://github.com/WordPress/ai/issues\">problemas abertos</a> e <a href=\"https://github.com/WordPress/ai/pulls\">pull requests</a> e <a href=\"https://github.com/WordPress/ai/discussions\">ajudar a definir o que vem a seguir</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Créditos a <a href=\'https://profiles.wordpress.org/dkotter/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>dkotter</a> pela revisão deste post.</em> </p>\n\n\n\n<p class=\"wp-block-paragraph\"><code>#ai-experiments</code>, <code>#ai-features</code>, <code>#ai-plugin</code>, <code>#ai-release</code>, <code>#canonical-plugins</code>, <code>#core-ai</code></p>\n\n\n\n<p class=\"wp-block-paragraph\">Tradução do post escrito por <a href=\'https://profiles.wordpress.org/jeffpaul/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>jeffpaul</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:84:\"https://br.wordpress.org/2026/09/16/novidades-no-ai-1-3-0-18-de-agosto-de-2026/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"3707\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:1;a:6:{s:4:\"data\";s:73:\"\n		\n		\n					\n		\n		\n		\n				\n		\n\n					\n										\n					\n					\n			\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:6:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:94:\"Explore o Terminal do WordPress Playground com o novo Dock de ferramentas para desenvolvedores\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:131:\"https://br.wordpress.org/2026/09/15/explore-o-terminal-do-wordpress-playground-com-o-novo-dock-de-ferramentas-para-desenvolvedores/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:139:\"https://br.wordpress.org/2026/09/15/explore-o-terminal-do-wordpress-playground-com-o-novo-dock-de-ferramentas-para-desenvolvedores/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 15 Sep 2026 16:17:25 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"Lançamentos\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://br.wordpress.org/?p=3710\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:331:\"O WordPress Playground lançou dois novos recursos: um Terminal integrado para PHP e WP-CLI e um grupo de opções de ferramentas para desenvolvedores no menu Dock. O Dock compacto mantém as ações do dia a dia à vista e oferece a quem desenvolve um caminho direto para as ferramentas de inspeção e de alteração de [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Fellyph Cintra\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:16337:\"\n<p class=\"wp-block-paragraph\">O WordPress Playground lançou dois novos recursos: um Terminal integrado para PHP e WP-CLI e um grupo de opções de ferramentas para desenvolvedores no menu Dock. O Dock compacto mantém as ações do dia a dia à vista e oferece a quem desenvolve um caminho direto para as ferramentas de inspeção e de alteração de um site.</p>\n\n\n\n<p class=\"wp-block-paragraph\">No Terminal, você pode inspecionar o conteúdo, verificar as configurações, testar uma API do WordPress ou fazer uma alteração rápida sem configurar um ambiente local nem sair de playground.wordpress.net. Os comandos são executados no Playground ativo: eles leem ou alteram o mesmo site WordPress exibido atrás do painel.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Ferramentas para desenvolvedores agrupadas no menu Dock</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Acesse <a href=\"https://playground.wordpress.net/\">playground.wordpress.net</a> e aguarde o WordPress iniciar. O Dock, na parte inferior da tela, mostra <strong>New</strong>, <strong>Playgrounds</strong>, <strong>Site Settings</strong>, <strong>Export</strong> e <strong>Dev Tools</strong>. Quando está no modo compacto, ele oculta os botões voltados ao desenvolvimento e oferece uma barra de ferramentas mais simples para quem está explorando o WordPress.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://br.wordpress.org/files/2026/09/dock-collapsed.png\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"668\" src=\"https://br.wordpress.org/files/2026/09/dock-collapsed-1024x668.png\" alt=\"\" class=\"wp-image-3711\" srcset=\"https://br.wordpress.org/files/2026/09/dock-collapsed-1024x668.png 1024w, https://br.wordpress.org/files/2026/09/dock-collapsed-300x196.png 300w, https://br.wordpress.org/files/2026/09/dock-collapsed-767x500.png 767w, https://br.wordpress.org/files/2026/09/dock-collapsed-1536x1002.png 1536w, https://br.wordpress.org/files/2026/09/dock-collapsed-2048x1335.png 2048w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Selecione <strong>Dev Tools</strong>, ao lado de <strong>Export</strong>, para expandir o Dock. As opções Blueprint, Database, Terminal, Files, Logs e Email aparecerão. Em seguida, selecione <strong>Terminal</strong> para abrir a ferramenta de execução de comandos do site atual.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://br.wordpress.org/files/2026/09/dock-expanded.png\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"668\" src=\"https://br.wordpress.org/files/2026/09/dock-expanded-1024x668.png\" alt=\"\" class=\"wp-image-3713\" srcset=\"https://br.wordpress.org/files/2026/09/dock-expanded-1024x668.png 1024w, https://br.wordpress.org/files/2026/09/dock-expanded-300x196.png 300w, https://br.wordpress.org/files/2026/09/dock-expanded-767x500.png 767w, https://br.wordpress.org/files/2026/09/dock-expanded-1536x1002.png 1536w, https://br.wordpress.org/files/2026/09/dock-expanded-2048x1335.png 2048w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<p class=\"wp-block-paragraph\">O Playground lembra se as ferramentas para desenvolvedores estavam visíveis ou ocultas mesmo após recarregar a página. Ao recolhê-las, ele mantém um comando inacabado no Terminal ou um rascunho de Blueprint, para que você possa reabrir a ferramenta e continuar.</p>\n\n\n\n<p class=\"wp-block-paragraph\">O outro novo recurso é o Terminal, que oferece dois modos:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><strong>PHP</strong> executa trechos curtos de código PHP com o WordPress já carregado.</li>\n\n\n\n<li><strong>WP-CLI</strong> executa comandos de linha de comando do WordPress no site ativo.</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Explorando WordPress com PHP</h2>\n\n\n\n<p class=\"wp-block-paragraph\">O modo PHP oferece um editor com realce de sintaxe, números de linha e alguns exemplos prontos para executar. Você pode selecionar exemplos como Versions, Site URL, List posts, Create post ou Active plugins, editar o código e selecionar <strong>Run</strong>.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://br.wordpress.org/files/2026/09/php-terminal.png\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"668\" src=\"https://br.wordpress.org/files/2026/09/php-terminal-1024x668.png\" alt=\"\" class=\"wp-image-3714\" srcset=\"https://br.wordpress.org/files/2026/09/php-terminal-1024x668.png 1024w, https://br.wordpress.org/files/2026/09/php-terminal-300x196.png 300w, https://br.wordpress.org/files/2026/09/php-terminal-767x500.png 767w, https://br.wordpress.org/files/2026/09/php-terminal-1536x1002.png 1536w, https://br.wordpress.org/files/2026/09/php-terminal-2048x1335.png 2048w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress já estará carregado, e a tag inicial <code>&lt;?php</code> é opcional. Por exemplo, este trecho lista os títulos dos posts do site:</p>\n\n\n<div class=\"wp-block-syntaxhighlighter-code \"><pre class=\"brush: php; title: ; notranslate\">\nforeach ( get_posts() as $post ) {\n	echo $post-&gt;post_title . &quot;\\n&quot;;\n}\n</pre></div>\n\n\n<p class=\"wp-block-paragraph\">Você também pode inspecionar versões e configurações:</p>\n\n\n<div class=\"wp-block-syntaxhighlighter-code \"><pre class=\"brush: php; title: ; notranslate\">\necho &#039;WordPress &#039; . get_bloginfo( &#039;version&#039; ) . &quot;\\n&quot;;\necho &#039;PHP &#039; . phpversion() . &quot;\\n&quot;;\necho &#039;Site URL: &#039; . get_site_url();\n</pre></div>\n\n\n<p class=\"wp-block-paragraph\">Cada execução é avaliada de forma independente. As variáveis de uma execução não ficam disponíveis na próxima, mas as alterações feitas pelas APIs do WordPress permanecem no Playground ativo. Por exemplo, <code>update_option()</code> altera o banco de dados do site da mesma forma que alteraria se fosse chamada por um plugin.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Use <strong>Ctrl+Enter</strong> ou <strong>Command+Enter</strong> para executar o código pelo teclado. Se o trecho estiver incompleto, ele permanecerá no editor para que você possa terminá-lo. Erros de sintaxe e de execução aparecem em mensagens concisas, com a posição no código quando essa informação está disponível.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Gerenciando WordPress com WP-CLI</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Mude para WP-CLI quando ela for a maneira mais rápida de inspecionar ou alterar o WordPress. Comece com um comando que apenas consulta dados:</p>\n\n\n<div class=\"wp-block-syntaxhighlighter-code \"><pre class=\"brush: bash; title: ; notranslate\">\nwp option get blogname\n</pre></div>\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://br.wordpress.org/files/2026/09/wp-cli-terminal.png\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"668\" src=\"https://br.wordpress.org/files/2026/09/wp-cli-terminal-1024x668.png\" alt=\"\" class=\"wp-image-3715\" srcset=\"https://br.wordpress.org/files/2026/09/wp-cli-terminal-1024x668.png 1024w, https://br.wordpress.org/files/2026/09/wp-cli-terminal-300x196.png 300w, https://br.wordpress.org/files/2026/09/wp-cli-terminal-767x500.png 767w, https://br.wordpress.org/files/2026/09/wp-cli-terminal-1536x1002.png 1536w, https://br.wordpress.org/files/2026/09/wp-cli-terminal-2048x1335.png 2048w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<p class=\"wp-block-paragraph\">O <code>wp</code> inicial é opcional; <code>option get blogname</code> também funciona. Na primeira execução de WP-CLI, o Playground baixa o executável, caso ele ainda não esteja disponível. Os comandos seguintes reutilizam esse executável.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Confira alguns comandos úteis. Execute cada linha separadamente:</p>\n\n\n<div class=\"wp-block-syntaxhighlighter-code \"><pre class=\"brush: bash; title: ; notranslate\">\nwp core version\nwp plugin list\nwp post list --fields=ID,post_title,post_status\nwp option get siteurl\n</pre></div>\n\n\n<p class=\"wp-block-paragraph\">Você também pode criar conteúdo diretamente:</p>\n\n\n<div class=\"wp-block-syntaxhighlighter-code \"><pre class=\"brush: bash; title: ; notranslate\">\nwp post create --post_title=&#039;Created from the Playground Terminal&#039; --post_status=publish\n</pre></div>\n\n\n<p class=\"wp-block-paragraph\">O resultado mostra <code>Success: Created post</code>, seguido do ID do post. Execute <code>wp post list --fields=ID,post_title,post_status</code> novamente para confirmar o título e o status de publicação. Para ver o post no WordPress, feche o Terminal, digite <code>/wp-admin/edit.php</code> no campo de endereço do Dock e abra o post na tela <strong>Posts</strong>. Apenas atualizar a página de boas-vindas não exibirá o novo post. Cada vez que você executar novamente o comando de criação, outro post será criado.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Simulando cenários reais</h2>\n\n\n\n<p class=\"wp-block-paragraph\">A WP-CLI é especialmente útil para preparar um site de testes antes de conferir o resultado no WordPress. Se você está desenvolvendo um plugin ou quer verificar como um tema se comporta em determinada tela, os exemplos a seguir mostram como preparar um Playground novo usando comandos do Terminal.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Inicie o <a href=\"https://playground.wordpress.net/?plugin=woocommerce\">Playground com o WooCommerce ativo</a>. O plugin acrescenta seus próprios comandos <code>wp wc</code>, e <code>--user=admin</code> concede a eles as permissões necessárias para gerenciar os dados da loja. Crie um produto de teste publicado e um cupom de 10% executando estes dois comandos separadamente:</p>\n\n\n<div class=\"wp-block-syntaxhighlighter-code \"><pre class=\"brush: bash; title: ; notranslate\">\nwp wc product create --name=&quot;Playground Test Mug&quot; --type=simple --status=publish --regular_price=19.99 --sku=playground-test-mug-01 --user=admin\n</pre></div>\n\n<div class=\"wp-block-syntaxhighlighter-code \"><pre class=\"brush: bash; title: ; notranslate\">\nwp wc shop_coupon create --code=PLAYGROUND10 --discount_type=percent --amount=10 --user=admin\n</pre></div>\n\n\n<p class=\"wp-block-paragraph\">Abra a loja no site WordPress, adicione <strong>Playground Test Mug</strong> ao carrinho e aplique <strong>PLAYGROUND10</strong> em <strong>Add coupons</strong>. Em um teste com um Playground novo, o produto apareceu por US$ 19,99, e o cupom reduziu o total do carrinho para US$ 17,99.</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><a href=\"https://br.wordpress.org/files/2026/09/discount.jpg\"><img loading=\"lazy\" decoding=\"async\" width=\"936\" height=\"818\" src=\"https://br.wordpress.org/files/2026/09/discount.jpg\" alt=\"\" class=\"wp-image-3716\" srcset=\"https://br.wordpress.org/files/2026/09/discount.jpg 936w, https://br.wordpress.org/files/2026/09/discount-300x262.jpg 300w, https://br.wordpress.org/files/2026/09/discount-768x671.jpg 768w\" sizes=\"auto, (max-width: 936px) 100vw, 936px\" /></a></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Os comandos criam os dados de teste; adicionar o produto ao carrinho e aplicar o cupom ainda são ações feitas no navegador. Consulte a <a href=\"https://developer.woocommerce.com/docs/wc-cli/using-wc-cli/\">referência de comandos do WooCommerce</a> para conhecer outras operações da loja.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Preparando posts para testar temas e o core do WordPress</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Quando um recurso precisa de mais de um post de exemplo, gere doze posts publicados com um único comando:</p>\n\n\n<div class=\"wp-block-syntaxhighlighter-code \"><pre class=\"brush: bash; title: ; notranslate\">\nwp post generate --count=12 --post_type=post --post_status=publish\n</pre></div>\n\n\n<p class=\"wp-block-paragraph\">Os posts gerados aparecem em <strong>Posts</strong>. No teste com o Playground, eles também preencheram a primeira página do blog e fizeram surgir uma segunda página de posts. Isso oferece conteúdo para testar paginação, ordenação, pesquisa ou ações em massa. Consulte a <a href=\"https://developer.wordpress.org/cli/commands/post/generate/\">referência do comando de geração de posts da WP-CLI</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Para um teste rápido e específico do editor de blocos, crie um post com conteúdo salvo como um bloco de parágrafo:</p>\n\n\n<div class=\"wp-block-syntaxhighlighter-code \"><pre class=\"brush: bash; title: ; notranslate\">\nwp post create --post_title=&#039;Block smoke test&#039; --post_status=publish --post_content=&#039;Block smoke test&#039;\n</pre></div>\n\n\n<p class=\"wp-block-paragraph\">Use o ID informado pelo comando para abrir <code>/wp-admin/post.php?post=ID&amp;action=edit</code>, substituindo <code>ID</code> pelo número do post. O post de teste foi aberto como um bloco de parágrafo no editor. Para testar o bloco de um plugin, substitua o conteúdo deste exemplo pelo conteúdo salvo correspondente ao bloco: se ele não corresponder à definição do bloco, poderá gerar um aviso de validação. O <a href=\"https://developer.wordpress.org/block-editor/getting-started/fundamentals/markup-representation-block/\">guia sobre a representação dos blocos no conteúdo salvo</a> explica o formato.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Um executor de comandos, não um shell completo.</h2>\n\n\n\n<p class=\"wp-block-paragraph\">O Terminal integrado é voltado a PHP e WP-CLI. Ele não é um shell de uso geral nem oferece um TTY interativo.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Inclua todos os valores necessários no próprio comando da WP-CLI. Comandos que aguardam uma entrada interativa são rejeitados, em vez de interpretar a entrada indisponível como um valor vazio. Comandos interativos de longa duração, como <code>wp shell</code> e <code>wp server</code>, não são compatíveis.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Essa restrição torna a execução no navegador mais previsível. Ela também impede que um comando altere inesperadamente o WordPress após uma tentativa malsucedida de ler a entrada padrão. O mesmo comportamento de falha imediata agora se aplica à etapa <code>wp-cli</code> do Blueprint. Por isso, os comandos de Blueprint também precisam fornecer explicitamente os argumentos necessários.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Um caminho mais rápido da pergunta à resposta.</h2>\n\n\n\n<p class=\"wp-block-paragraph\">O Terminal preenche o espaço entre navegar pelo <code>wp-admin</code> e montar um ambiente de desenvolvimento local. Quem desenvolve plugins pode verificar uma opção ou a lista de plugins ativos enquanto reproduz um erro. Quem escreve documentação ou está aprendendo pode executar exemplos de PHP no contexto do WordPress. Quem contribui com o projeto pode inspecionar um site de testes antes de exportá-lo ou compartilhar um Blueprint que permita reproduzir o cenário.</p>\n\n\n\n<p class=\"wp-block-paragraph\">O Terminal chegou à <a href=\"https://github.com/WordPress/wordpress-playground/pull/3808\">solicitação de alteração nº 3808, Add Terminal to the Dock</a>, a partir de um <a href=\"https://github.com/WordPress/wordpress-playground/issues/1340\">pedido anterior para integrar a WP-CLI ao site do Playground</a>. A <a href=\"https://github.com/WordPress/wordpress-playground/pull/4312\">atualização do Dock para Dev Tools</a> facilitou mostrar ou ocultar esse conjunto crescente de ferramentas.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Agradecemos a <a href=\'https://profiles.wordpress.org/akirk/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>akirk</a> pelo desenvolvimento do Terminal e às pessoas que criaram e aperfeiçoaram os controles do Dock.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Abra o <a href=\"https://playground.wordpress.net/\">WordPress Playground</a>, selecione <strong>Dev Tools <span aria-hidden=\"true\" class=\"wp-exclude-emoji\">→</span> Terminal</strong> e comece com <code>wp option get blogname</code> ou um dos exemplos de PHP. Ao terminar, recolha <strong>Dev Tools</strong> para voltar ao Dock mais simples. Se encontrar um erro ou tiver uma ideia para melhorar o fluxo de trabalho, <a href=\"https://github.com/WordPress/wordpress-playground/issues/new/choose\">abra uma issue no repositório do WordPress Playground</a> ou participe do canal <code>#playground</code> no <a href=\"https://make.wordpress.org/chat/\">Slack do Making WordPress</a>.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:136:\"https://br.wordpress.org/2026/09/15/explore-o-terminal-do-wordpress-playground-com-o-novo-dock-de-ferramentas-para-desenvolvedores/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"3710\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:2;a:6:{s:4:\"data\";s:54:\"\n		\n		\n		\n		\n		\n				\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:91:\"WordCamp Brasil 2026: dois dias de aprendizado, colaboração e conexões em Belo Horizonte\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:123:\"https://br.wordpress.org/2026/08/31/wordcamp-brasil-2026-dois-dias-de-aprendizado-colaboracao-e-conexoes-em-belo-horizonte/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 31 Aug 2026 17:02:18 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://br.wordpress.org/?p=3695\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:413:\"Nos dias 30 e 31 de outubro de 2026, Belo Horizonte receberá o WordCamp Brasil, um dos principais encontros da comunidade WordPress no país. O evento acontecerá na Universidade FUMEC e reunirá desenvolvedores, designers, profissionais de marketing, criadores de conteúdo, empreendedores, estudantes e todas as pessoas interessadas em WordPress, tecnologia, inovação, negócios digitais e software [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"Andre\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:9914:\"\n<figure class=\"wp-block-image size-large has-custom-border\"><a href=\"https://br.wordpress.org/files/2026/08/belo-horizonte.png\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"684\" src=\"https://br.wordpress.org/files/2026/08/belo-horizonte-1024x684.png\" alt=\"\" class=\"wp-image-3696\" style=\"border-top-left-radius:5px;border-top-right-radius:5px;border-bottom-left-radius:5px;border-bottom-right-radius:5px\" srcset=\"https://br.wordpress.org/files/2026/08/belo-horizonte-1024x684.png 1024w, https://br.wordpress.org/files/2026/08/belo-horizonte-300x200.png 300w, https://br.wordpress.org/files/2026/08/belo-horizonte-768x513.png 768w, https://br.wordpress.org/files/2026/08/belo-horizonte.png 1278w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Nos dias <strong>30 e 31 de outubro de 2026</strong>, Belo Horizonte receberá o WordCamp Brasil, um dos principais encontros da comunidade WordPress no país.</p>\n\n\n\n<p class=\"wp-block-paragraph\">O evento acontecerá na <strong>Universidade FUMEC</strong> e reunirá desenvolvedores, designers, profissionais de marketing, criadores de conteúdo, empreendedores, estudantes e todas as pessoas interessadas em WordPress, tecnologia, inovação, negócios digitais e software livre.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Serão dois dias com propostas diferentes, mas que se complementam: o primeiro será dedicado à colaboração com o projeto WordPress, enquanto o segundo contará com palestras, troca de conhecimentos e muitas oportunidades de networking.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Primeiro dia: Dia da Colaboração</strong></h2>\n\n\n\n<figure class=\"wp-block-image size-large has-custom-border\"><a href=\"https://br.wordpress.org/files/2026/08/20251125-wordcamp-16454.jpg\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"684\" src=\"https://br.wordpress.org/files/2026/08/20251125-wordcamp-16454-1024x684.jpg\" alt=\"\" class=\"wp-image-3698\" style=\"border-top-left-radius:5px;border-top-right-radius:5px;border-bottom-left-radius:5px;border-bottom-right-radius:5px\" srcset=\"https://br.wordpress.org/files/2026/08/20251125-wordcamp-16454-1024x684.jpg 1024w, https://br.wordpress.org/files/2026/08/20251125-wordcamp-16454-300x200.jpg 300w, https://br.wordpress.org/files/2026/08/20251125-wordcamp-16454-767x512.jpg 767w, https://br.wordpress.org/files/2026/08/20251125-wordcamp-16454-1536x1026.jpg 1536w, https://br.wordpress.org/files/2026/08/20251125-wordcamp-16454.jpg 1920w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a><figcaption class=\"wp-element-caption\">Dia do contribuidor &#8211; WordCamp Brasil 2025</figcaption></figure>\n\n\n\n<p class=\"wp-block-paragraph\">O WordCamp Brasil 2026 começa na <strong>sexta-feira, dia 30 de outubro</strong>, com o Dia da Colaboração.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Também conhecido na comunidade WordPress como <em>Contributor Day</em>, esse é um momento dedicado a contribuir diretamente com o desenvolvimento e o fortalecimento do WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Mas não se preocupe: você não precisa ser desenvolvedor ou saber programar para participar.</p>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress é construído por uma comunidade global e existem diversas formas de colaborar. Durante o dia, as pessoas participantes poderão conhecer as equipes do projeto e escolher aquela que mais combina com seus conhecimentos e interesses.</p>\n\n\n\n<p class=\"wp-block-paragraph\">É possível contribuir com áreas como:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Tradução;</li>\n\n\n\n<li>Marketing;</li>\n\n\n\n<li>Comunidade;</li>\n\n\n\n<li>Design;</li>\n\n\n\n<li>Documentação;</li>\n\n\n\n<li>Suporte;</li>\n\n\n\n<li>Acessibilidade;</li>\n\n\n\n<li>Testes;</li>\n\n\n\n<li>Desenvolvimento;</li>\n\n\n\n<li>Fotografia;</li>\n\n\n\n<li>Treinamento e educação.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">As atividades serão organizadas em grupos, com o acompanhamento de pessoas mais experientes da comunidade. Quem estiver participando pela primeira vez receberá orientações para entender como cada equipe funciona e como começar a colaborar.</p>\n\n\n\n<p class=\"wp-block-paragraph\">O Dia da Colaboração é uma oportunidade de aprender na prática, compartilhar conhecimentos e participar ativamente do projeto de código aberto que está presente em milhões de sites ao redor do mundo.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Além das atividades, teremos um <strong>coffee break</strong>, criando mais um momento para conversar, conhecer outras pessoas e trocar experiências com a comunidade.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Segundo dia: palestras, conhecimento e networking</strong></h2>\n\n\n\n<figure class=\"wp-block-image size-large has-custom-border\"><a href=\"https://br.wordpress.org/files/2026/08/20251125-wordcamp-16712-e1788194754556.jpg\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"514\" src=\"https://br.wordpress.org/files/2026/08/20251125-wordcamp-16712-e1788194754556-1024x514.jpg\" alt=\"\" class=\"wp-image-3699\" style=\"border-top-left-radius:5px;border-top-right-radius:5px;border-bottom-left-radius:5px;border-bottom-right-radius:5px\" srcset=\"https://br.wordpress.org/files/2026/08/20251125-wordcamp-16712-e1788194754556-1024x514.jpg 1024w, https://br.wordpress.org/files/2026/08/20251125-wordcamp-16712-e1788194754556-300x150.jpg 300w, https://br.wordpress.org/files/2026/08/20251125-wordcamp-16712-e1788194754556-768x385.jpg 768w, https://br.wordpress.org/files/2026/08/20251125-wordcamp-16712-e1788194754556-1536x770.jpg 1536w, https://br.wordpress.org/files/2026/08/20251125-wordcamp-16712-e1788194754556.jpg 1920w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a><figcaption class=\"wp-element-caption\">WordCamp Brasil 2025</figcaption></figure>\n\n\n\n<p class=\"wp-block-paragraph\">No <strong>sábado, dia 31 de outubro</strong>, teremos um dia inteiro de palestras com profissionais de diferentes áreas do ecossistema WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A programação será pensada para pessoas com diferentes níveis de experiência, desde quem está começando a conhecer o WordPress até profissionais que já trabalham com desenvolvimento, criação de sites, conteúdo, marketing, design, negócios digitais e tecnologia.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Durante o dia, as pessoas participantes poderão acompanhar conteúdos sobre diferentes temas, conhecer novas ferramentas, descobrir tendências, aprender com experiências reais e encontrar ideias para aplicar em seus projetos e negócios.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Entre as palestras, haverá intervalos destinados ao networking. Esses momentos são parte importante da experiência do WordCamp: uma oportunidade para conhecer profissionais de diferentes regiões, conversar com palestrantes, visitar os espaços dos patrocinadores, compartilhar projetos e criar novas conexões.</p>\n\n\n\n<p class=\"wp-block-paragraph\">No segundo dia, o evento também contará com <strong>coffee break e almoço</strong>, permitindo que as pessoas participantes aproveitem toda a programação com mais conforto e tenham ainda mais tempo para interagir com a comunidade.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Muito mais do que uma conferência</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">O WordCamp Brasil não é apenas um evento de palestras. É um encontro feito pela comunidade e para a comunidade.</p>\n\n\n\n<p class=\"wp-block-paragraph\">É um espaço aberto para aprender, colaborar, ensinar, fazer perguntas, compartilhar experiências e conhecer pessoas que utilizam o WordPress de diferentes maneiras.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Você pode participar mesmo que ainda esteja começando, nunca tenha ido a um evento de tecnologia ou não trabalhe diretamente com desenvolvimento. O WordCamp reúne diferentes conhecimentos, trajetórias e perspectivas, sempre com o objetivo de tornar a comunidade WordPress mais diversa, acessível e colaborativa.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Anote na agenda</strong></h2>\n\n\n\n<figure class=\"wp-block-image size-full has-custom-border\"><a href=\"https://br.wordpress.org/files/2026/08/FACE-atual.png\"><img loading=\"lazy\" decoding=\"async\" width=\"1000\" height=\"864\" src=\"https://br.wordpress.org/files/2026/08/FACE-atual.png\" alt=\"\" class=\"wp-image-3702\" style=\"border-top-left-radius:5px;border-top-right-radius:5px;border-bottom-left-radius:5px;border-bottom-right-radius:5px\" srcset=\"https://br.wordpress.org/files/2026/08/FACE-atual.png 1000w, https://br.wordpress.org/files/2026/08/FACE-atual-300x259.png 300w, https://br.wordpress.org/files/2026/08/FACE-atual-767x663.png 767w\" sizes=\"auto, (max-width: 1000px) 100vw, 1000px\" /></a><figcaption class=\"wp-element-caption\">FUMEC &#8211; Belo Horizonte / MG</figcaption></figure>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>WordCamp Brasil 2026<br></strong><img src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f4c5.png\" alt=\"📅\" class=\"wp-smiley\" style=\"height: 1em; max-height: 1em;\" /> 30 e 31 de outubro de 2026<br><img src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f4cd.png\" alt=\"📍\" class=\"wp-smiley\" style=\"height: 1em; max-height: 1em;\" /> Universidade FUMEC<br>Rua Cobre, 200 – bairro Cruzeiro<br>Belo Horizonte – MG</p>\n\n\n\n<p class=\"wp-block-paragraph\">A programação detalhada, incluindo os horários das atividades, palestras e intervalos, será divulgada nos canais oficiais do evento.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Prepare-se para dois dias de muito conhecimento, colaboração, troca de experiências e novas conexões.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Acompanhe as novidades no <a href=\"https://brasil.wordcamp.org/2026/\"></a><a href=\"https://brasil.wordcamp.org/2026/\"><u>site oficial do WordCamp Brasil 2026</u></a> e garanta seu ingresso.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Esperamos você em Belo Horizonte!</p>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"3695\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:3;a:6:{s:4:\"data\";s:60:\"\n		\n		\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"WordPress 7.1 “Mary Lou”\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:59:\"https://br.wordpress.org/2026/08/19/wordpress-7-1-mary-lou/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 20 Aug 2026 00:26:16 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:12:\"Lançamentos\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:3:\"7.1\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://br.wordpress.org/?p=3679\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:382:\"Cada lançamento do WordPress celebra um artista que deixou uma marca inesquecível no mundo da música. O WordPress 7.1, codinome “Mary Lou”, homenageia a pioneira pianista de jazz, arranjadora e compositora Mary Lou Williams. Uma criança prodígio que começou a tocar publicamente aos seis anos, sua influência e trabalho atravessam quase todas as principais eras [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"Andre\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:88039:\"\n<figure class=\"wp-block-image size-large\"><a href=\"https://br.wordpress.org/files/2026/08/release-edition-featured-image-7-1-scaled-1.png\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"534\" src=\"https://br.wordpress.org/files/2026/08/release-edition-featured-image-7-1-scaled-1-1024x534.png\" alt=\"\" class=\"wp-image-3681\" srcset=\"https://br.wordpress.org/files/2026/08/release-edition-featured-image-7-1-scaled-1-1024x534.png 1024w, https://br.wordpress.org/files/2026/08/release-edition-featured-image-7-1-scaled-1-300x157.png 300w, https://br.wordpress.org/files/2026/08/release-edition-featured-image-7-1-scaled-1-768x401.png 768w, https://br.wordpress.org/files/2026/08/release-edition-featured-image-7-1-scaled-1-1536x802.png 1536w, https://br.wordpress.org/files/2026/08/release-edition-featured-image-7-1-scaled-1.png 1872w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Cada lançamento do WordPress celebra um artista que deixou uma marca inesquecível no mundo da música. O <a href=\"https://wordpress.org/download/releases/7-1/\">WordPress 7.1</a>, codinome “Mary Lou”, homenageia a pioneira pianista de jazz, arranjadora e compositora Mary Lou Williams.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Uma criança prodígio que começou a tocar publicamente aos seis anos, sua influência e trabalho atravessam quase todas as principais eras do jazz, movendo-se através do swing, bebop e jazz sagrado. Através de tudo isso, ela continuou reinventando seu próprio som. Na década de 1940, ela transformou seu apartamento no Harlem em uma oficina noturna onde Thelonious Monk, Dizzy Gillespie e Bud Powell vieram para trocar ideias e moldar o próprio bebop. Essa combinação de reinvenção e colaboração inspirou o WordPress 7.1.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Deixe a gama de <a href=\"https://www.youtube.com/channel/UCha4zVvYM9Tv8Hx0Q9lN_jQ\" target=\"_blank\" rel=\"noopener\">músicas de Mary Lou</a> levá-lo através de tudo o que 7.1 oferece.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Boas vindas ao WordPress 7.1!</h2>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.1 é construído em torno de como você trabalha: navegando no administrador, controlando seus projetos, colaborando com outras pessoas e construindo o que você quer. A barra de administração agora segue você em toda a experiência de administrador, colocando as ferramentas que você precisa ao alcance, esteja você escrevendo um post ou editando o design do seu site. Estilo responsivo integrado, adicionado às opções atuais de exibição para blocos, significa que você pode garantir que seu site pareça exatamente como deseja em diferentes tamanhos de tela, sem CSS personalizado. Um novo editor de mídia mantém familiar o acesso ao botão de recortar e traz corte de forma livre, com proporção, flipping horizontal e vertical, rotação fina e edição de metadados em um fluxo de trabalho dedicado. Deixe anotações em qualquer lugar do seu conteúdo, não mais limitado ao nível de bloco. O suporte de texto rico e o @mentions facilitam a colaboração com outras pessoas enquanto você escreve. Dois novos blocos, Playlist e Abas, bem como uma nova API para registrar seu próprio conjunto de ícones para o bloco de ícones, oferecem ainda mais flexibilidade para criar o que você deseja sem plugins adicionais. Estes são apenas os destaques! Continue lendo para ver tudo o que o WordPress 7.1 tem a oferecer.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://wordpress.org/wordpress-7.1.zip\">Baixar WordPress 7.1</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">O que há de novo</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Há muita coisa embalada no WordPress 7.1 em novas ferramentas de estilo, fluxos de mídia atualizados, funcionalidade adicionada de anotações e muito mais. Algumas mudanças adicionam novos recursos, enquanto outras refinam ferramentas e fluxos de trabalho existentes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Aqui está um olhar mais atento sobre o que há de novo neste lançamento, começando com o vídeo de lançamento:</p>\n\n\n\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n<iframe loading=\"lazy\" class=\"youtube-player\" width=\"640\" height=\"360\" src=\"https://www.youtube.com/embed/dO751c8jkn0?version=3&#038;rel=1&#038;showsearch=0&#038;showinfo=1&#038;iv_load_policy=1&#038;fs=1&#038;hl=pt-BR&#038;autohide=2&#038;wmode=transparent\" allowfullscreen=\"true\" style=\"border:0;\" sandbox=\"allow-scripts allow-same-origin allow-popups allow-presentation allow-popups-to-escape-sandbox\"></iframe>\n</div></figure>\n\n\n\n<h3 class=\"wp-block-heading\">Aplicar estilos responsivos</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Estilo seu conteúdo do seu jeito, em todas as telas.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.1 traz mais controles responsivos diretamente para o editor do site. Estilos de blocos respeitam diferentes tamanhos de tela de estilos globais ou de configurações de blocos individuais, sem CSS personalizado. Você também pode visualizar suas alterações em diferentes tamanhos de tela à medida que trabalha, tornando simples a criação de layouts que se adaptam à maneira como as pessoas navegam na web.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://br.wordpress.org/files/2026/08/Apply-responsive-styles-scaled-1.png\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"632\" src=\"https://br.wordpress.org/files/2026/08/Apply-responsive-styles-scaled-1-1024x632.png\" alt=\"\" class=\"wp-image-3682\" srcset=\"https://br.wordpress.org/files/2026/08/Apply-responsive-styles-scaled-1-1024x632.png 1024w, https://br.wordpress.org/files/2026/08/Apply-responsive-styles-scaled-1-300x185.png 300w, https://br.wordpress.org/files/2026/08/Apply-responsive-styles-scaled-1-768x474.png 768w, https://br.wordpress.org/files/2026/08/Apply-responsive-styles-scaled-1-1536x948.png 1536w, https://br.wordpress.org/files/2026/08/Apply-responsive-styles-scaled-1.png 1582w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<h3 class=\"wp-block-heading\">Barra do admin agora em cada editor</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Navegação consistente, do painel ao editor.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">A barra de administração do WordPress agora permanece com você enquanto você se move em todos os editores, para que você sempre saiba onde está e tenha acesso fácil a ferramentas familiares. A barra de administração também possui algumas pequenas atualizações visuais para polir mais completamente a experiência.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://br.wordpress.org/files/2026/08/Admin-bar-now-in-every-editor-scaled-1.png\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"632\" src=\"https://br.wordpress.org/files/2026/08/Admin-bar-now-in-every-editor-scaled-1-1024x632.png\" alt=\"\" class=\"wp-image-3683\" srcset=\"https://br.wordpress.org/files/2026/08/Admin-bar-now-in-every-editor-scaled-1-1024x632.png 1024w, https://br.wordpress.org/files/2026/08/Admin-bar-now-in-every-editor-scaled-1-300x185.png 300w, https://br.wordpress.org/files/2026/08/Admin-bar-now-in-every-editor-scaled-1-768x474.png 768w, https://br.wordpress.org/files/2026/08/Admin-bar-now-in-every-editor-scaled-1-1536x948.png 1536w, https://br.wordpress.org/files/2026/08/Admin-bar-now-in-every-editor-scaled-1.png 1581w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<h3 class=\"wp-block-heading\">Uma nova forma de corte</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Um fluxo de trabalho dedicado para editar suas imagens.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Um novo modal de editor de mídia substitui a ferramenta de corte em linha anterior, reunindo corte de livre forma e proporção, inversão horizontal e vertical, controle de rotação preciso e edição de metadados juntos em um só lugar. O familiar botão de corte ainda te leva até lá.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://br.wordpress.org/files/2026/08/A-new-way-to-crop-scaled-1.png\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"632\" src=\"https://br.wordpress.org/files/2026/08/A-new-way-to-crop-scaled-1-1024x632.png\" alt=\"\" class=\"wp-image-3685\" srcset=\"https://br.wordpress.org/files/2026/08/A-new-way-to-crop-scaled-1-1024x632.png 1024w, https://br.wordpress.org/files/2026/08/A-new-way-to-crop-scaled-1-300x185.png 300w, https://br.wordpress.org/files/2026/08/A-new-way-to-crop-scaled-1-768x474.png 768w, https://br.wordpress.org/files/2026/08/A-new-way-to-crop-scaled-1-1536x948.png 1536w, https://br.wordpress.org/files/2026/08/A-new-way-to-crop-scaled-1.png 1583w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<h3 class=\"wp-block-heading\">Notas em linha com menções e texto rico</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Mais maneiras de deixar seu feedback.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">As notas agora suportam texto rico e menções, tornando mais fácil deixar feedback claro e notificar as pessoas certas. Formate suas anotações com negrito, itálico e código, adicione links ou digite <code>@</code> para mencionar um colaborador e notificá-los.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Você também pode deixar uma nota em uma parte específica de texto em vez de apenas no bloco inteiro, manter várias conversas no mesmo bloco e colapsar notas mais longas para manter a margem arrumada. Ele é construído para o vai e vem que acontece quando as pessoas revisam um conteúdo simultaneamente.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://br.wordpress.org/files/2026/08/Inline-notes-with-mentions-and-rich-text-scaled-1.png\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"633\" src=\"https://br.wordpress.org/files/2026/08/Inline-notes-with-mentions-and-rich-text-scaled-1-1024x633.png\" alt=\"\" class=\"wp-image-3686\" srcset=\"https://br.wordpress.org/files/2026/08/Inline-notes-with-mentions-and-rich-text-scaled-1-1024x633.png 1024w, https://br.wordpress.org/files/2026/08/Inline-notes-with-mentions-and-rich-text-scaled-1-300x186.png 300w, https://br.wordpress.org/files/2026/08/Inline-notes-with-mentions-and-rich-text-scaled-1-768x475.png 768w, https://br.wordpress.org/files/2026/08/Inline-notes-with-mentions-and-rich-text-scaled-1-1536x950.png 1536w, https://br.wordpress.org/files/2026/08/Inline-notes-with-mentions-and-rich-text-scaled-1.png 1581w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<h3 class=\"wp-block-heading\">Melhoria do manuseio de mídia</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Processamento de imagem mais rápido e mais flexível.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">A compressão de imagens, o redimensionamento e a geração de miniaturas agora acontecem no navegador, reduzindo a carga do servidor e produzindo arquivos menores, sem afetar os limites de memória do PHP ou fazer atingindo tempo limite.</p>\n\n\n\n<p class=\"wp-block-paragraph\">O manuseio de mídia na versão 7.1 também inclui suporte nativo para formatos AVIF, HEIC e HDR, adicionando suporte nativo para os formatos de imagem que câmeras e telefones modernos já produzem.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://br.wordpress.org/files/2026/08/More-image-formats-with-faster-uploads-scaled-1.png\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"630\" src=\"https://br.wordpress.org/files/2026/08/More-image-formats-with-faster-uploads-scaled-1-1024x630.png\" alt=\"\" class=\"wp-image-3687\" srcset=\"https://br.wordpress.org/files/2026/08/More-image-formats-with-faster-uploads-scaled-1-1024x630.png 1024w, https://br.wordpress.org/files/2026/08/More-image-formats-with-faster-uploads-scaled-1-300x185.png 300w, https://br.wordpress.org/files/2026/08/More-image-formats-with-faster-uploads-scaled-1-768x473.png 768w, https://br.wordpress.org/files/2026/08/More-image-formats-with-faster-uploads-scaled-1-1536x945.png 1536w, https://br.wordpress.org/files/2026/08/More-image-formats-with-faster-uploads-scaled-1.png 1583w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<h3 class=\"wp-block-heading\">Detalhes aprimorados e novos blocos</h3>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.1 também adiciona dois novos blocos, juntamente com mais maneiras de personalizar como o conteúdo se parece e se comporta.</p>\n\n\n\n<h4 class=\"wp-block-heading\">Criar playlists</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Reúna várias faixas de áudio em uma lista de reprodução, com uma forma de dar aos ouvintes uma noção visual de cada faixa à medida que ela é reproduzida.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://br.wordpress.org/files/2026/08/Create-playlists-scaled-1.png\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"632\" src=\"https://br.wordpress.org/files/2026/08/Create-playlists-scaled-1-1024x632.png\" alt=\"\" class=\"wp-image-3688\" srcset=\"https://br.wordpress.org/files/2026/08/Create-playlists-scaled-1-1024x632.png 1024w, https://br.wordpress.org/files/2026/08/Create-playlists-scaled-1-300x185.png 300w, https://br.wordpress.org/files/2026/08/Create-playlists-scaled-1-768x474.png 768w, https://br.wordpress.org/files/2026/08/Create-playlists-scaled-1-1536x948.png 1536w, https://br.wordpress.org/files/2026/08/Create-playlists-scaled-1.png 1583w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<h4 class=\"wp-block-heading\">Personalize tamanhos de tela responsivos</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Os temas de bloco agora podem definir seus próprios tamanhos de telas de dispositivos móveis e tablets no arquivo <em>theme.json</em>, substituindo os padrões de estilos responsivos e visibilidade do bloco.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://br.wordpress.org/files/2026/08/Customize-responsive-breakpoints-scaled-1.png\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"633\" src=\"https://br.wordpress.org/files/2026/08/Customize-responsive-breakpoints-scaled-1-1024x633.png\" alt=\"\" class=\"wp-image-3689\" srcset=\"https://br.wordpress.org/files/2026/08/Customize-responsive-breakpoints-scaled-1-1024x633.png 1024w, https://br.wordpress.org/files/2026/08/Customize-responsive-breakpoints-scaled-1-300x185.png 300w, https://br.wordpress.org/files/2026/08/Customize-responsive-breakpoints-scaled-1-768x474.png 768w, https://br.wordpress.org/files/2026/08/Customize-responsive-breakpoints-scaled-1-1536x949.png 1536w, https://br.wordpress.org/files/2026/08/Customize-responsive-breakpoints-scaled-1.png 1580w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<h4 class=\"wp-block-heading\">Organize com guias</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Organize o conteúdo em painéis com guias em vez de mostrar tudo de uma só vez, uma maneira mais limpa de apresentar informações relacionadas sem aglomerar seu conteúdo.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://br.wordpress.org/files/2026/08/Organize-with-tabs-scaled-1.png\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"631\" src=\"https://br.wordpress.org/files/2026/08/Organize-with-tabs-scaled-1-1024x631.png\" alt=\"\" class=\"wp-image-3690\" srcset=\"https://br.wordpress.org/files/2026/08/Organize-with-tabs-scaled-1-1024x631.png 1024w, https://br.wordpress.org/files/2026/08/Organize-with-tabs-scaled-1-300x185.png 300w, https://br.wordpress.org/files/2026/08/Organize-with-tabs-scaled-1-768x474.png 768w, https://br.wordpress.org/files/2026/08/Organize-with-tabs-scaled-1-1536x947.png 1536w, https://br.wordpress.org/files/2026/08/Organize-with-tabs-scaled-1.png 1581w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<h4 class=\"wp-block-heading\">Adicionar ícones personalizados</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Os desenvolvedores podem estender a biblioteca de ícones do WordPress com suas próprias coleções, disponibilizando ícones personalizados em todo o editor ao lado da biblioteca interna.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://br.wordpress.org/files/2026/08/Add-custom-icons-scaled-1.png\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"631\" src=\"https://br.wordpress.org/files/2026/08/Add-custom-icons-scaled-1-1024x631.png\" alt=\"\" class=\"wp-image-3691\" srcset=\"https://br.wordpress.org/files/2026/08/Add-custom-icons-scaled-1-1024x631.png 1024w, https://br.wordpress.org/files/2026/08/Add-custom-icons-scaled-1-300x185.png 300w, https://br.wordpress.org/files/2026/08/Add-custom-icons-scaled-1-768x474.png 768w, https://br.wordpress.org/files/2026/08/Add-custom-icons-scaled-1-1536x947.png 1536w, https://br.wordpress.org/files/2026/08/Add-custom-icons-scaled-1.png 1581w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<h4 class=\"wp-block-heading\">Definir estilos interativos</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Dê aos blocos de botão estilos distintos para focar e estados ativos diretamente nos controles de estilo do editor. Defina os estilos para apenas um botão ou todos os botões.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://br.wordpress.org/files/2026/08/Set-interactive-styles-scaled-1.png\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"633\" src=\"https://br.wordpress.org/files/2026/08/Set-interactive-styles-scaled-1-1024x633.png\" alt=\"\" class=\"wp-image-3692\" srcset=\"https://br.wordpress.org/files/2026/08/Set-interactive-styles-scaled-1-1024x633.png 1024w, https://br.wordpress.org/files/2026/08/Set-interactive-styles-scaled-1-300x185.png 300w, https://br.wordpress.org/files/2026/08/Set-interactive-styles-scaled-1-768x474.png 768w, https://br.wordpress.org/files/2026/08/Set-interactive-styles-scaled-1-1536x949.png 1536w, https://br.wordpress.org/files/2026/08/Set-interactive-styles-scaled-1.png 1583w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<h3 class=\"wp-block-heading\">Uma experiência de edição mais consistente</h3>\n\n\n\n<p class=\"wp-block-paragraph\">O editor de posts agora está totalmente preparado para todos os temas, combinando com o editor do site.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A tela de edição é executada separadamente da interface de administração do WordPress, para que os estilos de administrador não interfiram no seu conteúdo. Unidades e consultas de mídia relacionadas ao tamanho da tela agora segmentam a tela de edição diretamente, e consequentemente os layouts responsivos se comportam de forma mais previsível à medida que você constrói. A mudança é praticamente invisível, mas o resultado é um editor mais confiável e consistente.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Ferramentas do desenvolvedor</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Ferramentas avançadas para construir o seu caminho.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.1 expande várias das APIs e ferramentas que os desenvolvedores usam para construir no WordPress, com novas opções para ícones, automação, interfaces de administração e estilo responsivo.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A API SVG Icon agora é uma API pública, permitindo que os desenvolvedores registrem suas próprias coleções de ícones e os usem em todo o editor com funções como <code>wp_register_icon_collection(), wp_register_icon(), and wp_get_icon().</code></p>\n\n\n\n<p class=\"wp-block-paragraph\">A API de Habilidades baseia-se na infraestrutura introduzida no WordPress 6.9 com um ciclo de vida de execução filtrável, validação personalizada e descoberta compartilhada. Essas adições facilitam a criação de integrações e automação em cima do WordPress, incluindo ferramentas alimentadas por IA.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Um novo sistema de design fornece suporte fundamental para a temática de interfaces de administração do WordPress, incluindo cores estilos. Os desenvolvedores podem usar tokens de design semântico e o componente <code>ThemeProvider</code> do React para trazer mais consistência para interfaces de administração personalizadas enquanto ainda se sente em casa no WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Os autores do tema também recebem estilo responsivo e estilo de pseudo-estado para hover, foco, foco-visível e estados ativos através de <code>theme.json</code>, juntamente com novos filtros para configurar as telas DataViews e DataForm que alimentam páginas, modelos, partes e padrões no editor de sites.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Acessibilidade</h2>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.1 continua a melhorar a acessibilidade em todo o núcleo e no editor. Novas funções <code>wp_get_tooltip()</code>e <code>wp_get_toggletip()</code> trazem dicas de ferramentas acessíveis para mais áreas do administrador do WordPress, incluindo caixas de metadados de posts e a tela de login.</p>\n\n\n\n<p class=\"wp-block-paragraph\">O suporte ao leitor de tela também foi melhorado em todas as interfaces de administração, com rotulagem mais clara e navegação mais previsível nas tabelas de lista de posts. Os novos blocos de Abas e Playlist, juntamente com melhorias na navegação e interação do editor, aumentam o trabalho de acessibilidade mais amplo incluído nesta versão.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Juntas, essas mudanças continuam a tornar o WordPress mais fácil de navegar e usar para mais pessoas.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Melhorias de desempenho</h2>\n\n\n\n<p class=\"wp-block-paragraph\">A compressão de imagens, o redimensionamento e a geração de miniaturas agora são executados no navegador (através de uma compilação do WebAssembly do libvips), reduzindo a carga de processamento em seu servidor e ajudando a evitar limites de memória e tempo limite com envios maiores.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A conversão de GIF-to-video produz arquivos tipicamente menores, enquanto os indicadores de progresso e as retomadas automáticas tornam os envios mais resilientes quando as conexões caem.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A biblioteca de mídia agora usa rolagem infinita por padrão, com uma opção para o usuário retornar à paginação. Os padrões de carregamento especulativo agora podem ser definidos por meio de variáveis de ambiente ou constantes, para que os proprietários de hospedagens e sites possam configurar como o WordPress pré-busca as páginas sem escrever um plugin.</p>\n\n\n\n<h2 class=\"wp-block-heading\">E muito mais!</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Para uma visão geral abrangente de tudo o que ha de novo e melhorado no WordPress 7.1, visite o site de apresentação dos recursos.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://wordpress.org/download/releases/7-1/\">Confira o que há de novo no 7.1</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">Saiba mais sobre o WordPress 7.1</h2>\n\n\n\n<p class=\"wp-block-paragraph\">O <a href=\"https://learn.wordpress.org/\">Learn WordPress</a> é um recurso gratuito para usuários novos e experientes do WordPress. O Learn é abastecido com vídeos de instruções sobre o uso de vários recursos no WordPress, <a href=\"https://learn.wordpress.org/social-learning/\">workshops interativos</a> para explorar tópicos aprofundados e planos de aula para mergulhar profundamente em áreas específicas do WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Leia as <a href=\"https://wordpress.org/documentation/wordpress-version/version-7.1/\">Notas de versãodo WordPress 7.1</a> para obter informações sobre instalação, aprimoramentos, problemas corrigidos, contribuidores de versão, recursos de aprendizado e a lista de alterações de arquivos.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Explore o <a href=\"https://make.wordpress.org/core/2026/08/05/wordpress-7-1-field-guide/\">guia de campo do WordPress 7.1</a>. Saiba mais sobre as mudanças nesta versão com notas detalhadas dos desenvolvedores para ajudá-lo a construir com o WordPress.</p>\n\n\n\n<h2 class=\"wp-block-heading\">O esquadrão de lançamento</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Cada lançamento vem para você de uma equipe dedicada de colaboradores entusiastas que ajudam a manter as coisas no caminho certo e se movendo sem problemas. A equipe que liderou a versão 7.1 é um grupo multifuncional de colaboradores que estão sempre prontos para defender ideias, remover bloqueadores e resolver problemas.</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Liderança de lançamento: <a href=\"https://profiles.wordpress.org/annezazu/\">Anne McCarthy</a>.</li>\n\n\n\n<li>Coordenação de Lançamento: <a href=\"https://profiles.wordpress.org/benjamin_zekavica/\">Benjamin Zekavica</a> e <a href=\"https://profiles.wordpress.org/krupajnanda/\">Krupa Nanda</a>.</li>\n\n\n\n<li>Líderes técnicos: <a href=\"https://profiles.wordpress.org/wildworks/\">Aki Hamano</a> e <a href=\"https://profiles.wordpress.org/joedolson/\">Joe Dolson</a>.</li>\n\n\n\n<li>Liderança de triagem: <a href=\"https://profiles.wordpress.org/adrianduffell/\">Adrian Duffell</a>, <a href=\"https://profiles.wordpress.org/sajjad67/\">Sajjad Hossain Sagor</a> e <a href=\"https://profiles.wordpress.org/sergeybiryukov/\">Sergey Biryukov</a>.</li>\n\n\n\n<li>Liderança dos teste: <a href=\"https://profiles.wordpress.org/huzaifaalmesbah/\">Huzaifa Al Mesbah</a> e <a href=\"https://profiles.wordpress.org/nikunj8866/\">Nikunj Hatkar</a>.</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Agradecimento aos colaboradores</h2>\n\n\n\n<p class=\"wp-block-paragraph\">A missão do WordPress é <a href=\"https://wordpress.org/about/\">democratizar</a> a publicação e <a href=\"https://opensource.org/osd-annotated\">incorporar as liberdades que vêm com o código aberto</a>. Uma comunidade global e diversificada de pessoas colaborando para fortalecer o software apoia esse esforço.</p>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.1 reflete os esforços incansáveis e a paixão de mais de 800 colaboradores de todo o mundo. Este lançamento também recebeu mais de 170 colaboradores pela primeira vez!</p>\n\n\n\n<p class=\"wp-block-paragraph\">Juntos, seus trabalhos entregaram mais de 1500 aprimoramentos e correções, ajudando a tornar o WordPress 7.1 uma versão estável e polida para todos. É outro grande exemplo do que a comunidade de código aberto do WordPress pode realizar quando as pessoas se reúnem para construir, testar e melhorar o software.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://profiles.wordpress.org/ishihara-takashi/\">1shiharaT</a> · <a href=\"https://profiles.wordpress.org/aagam94/\">Aagam Shah</a> · <a href=\"https://profiles.wordpress.org/aakashverma1/\">Aakash Verma</a> · <a href=\"https://profiles.wordpress.org/aaroncampbell/\">Aaron D. Campbell</a> · <a href=\"https://profiles.wordpress.org/jorbin/\">Aaron Jorbin</a> · <a href=\"https://profiles.wordpress.org/aaronrobertshaw/\">Aaron Robertshaw</a> · <a href=\"https://profiles.wordpress.org/abdalsalaam/\">Abdalsalaam Halawa</a> · <a href=\"https://profiles.wordpress.org/abdullahramzan/\">Abdullah Ramzan</a> · <a href=\"https://profiles.wordpress.org/abduremon/\">Abdur Rahman Emon</a> · <a href=\"https://profiles.wordpress.org/abhishekfdd/\">Abhishek Kumar</a> · <a href=\"https://profiles.wordpress.org/ibachal/\">Achal Jain</a> · <a href=\"https://profiles.wordpress.org/adamsilverstein/\">Adam Silverstein</a> · <a href=\"https://profiles.wordpress.org/adamwood/\">Adam Wood</a> · <a href=\"https://profiles.wordpress.org/zieladam/\">Adam Zieliński</a> · <a href=\"https://profiles.wordpress.org/adrianmoldovanwp/\">Adi Moldovan</a> · <a href=\"https://profiles.wordpress.org/adithyanaik/\">adithyanaik</a> · <a href=\"https://profiles.wordpress.org/iamadisingh/\">Aditya Singh</a> · <a href=\"https://profiles.wordpress.org/adrianduffell/\">Adrian Duffell</a> · <a href=\"https://profiles.wordpress.org/adrmf25/\">adrmf25</a> · <a href=\"https://profiles.wordpress.org/agulbra/\">agulbra</a> · <a href=\"https://profiles.wordpress.org/elazzabi/\">Ahmed</a> · <a href=\"https://profiles.wordpress.org/chaion07/\">Ahmed Kabir Chaion</a> · <a href=\"https://profiles.wordpress.org/ahuseyn/\">ahuseyn</a> · <a href=\"https://profiles.wordpress.org/wildworks/\">Aki Hamano</a> · <a href=\"https://profiles.wordpress.org/akshat2802/\">Akshat Kakkad</a> · <a href=\"https://profiles.wordpress.org/schlessera/\">Alain Schlesser</a> · <a href=\"https://profiles.wordpress.org/alanjacobmathew/\">Alan Jacob Mathew</a> · <a href=\"https://profiles.wordpress.org/aljullu/\">Albert Juhé Lluveras</a> · <a href=\"https://profiles.wordpress.org/alecgeatches/\">Alec Geatches</a> · <a href=\"https://profiles.wordpress.org/xknown/\">Alex Concha</a> · <a href=\"https://profiles.wordpress.org/alexcu21/\">Alex Cuadra</a> · <a href=\"https://profiles.wordpress.org/akirk/\">Alex Kirk</a> · <a href=\"https://profiles.wordpress.org/alexstine/\">Alex Stine</a> · <a href=\"https://profiles.wordpress.org/alhrath/\">alhrath</a> · <a href=\"https://profiles.wordpress.org/firewatch/\">allilevine</a> · <a href=\"https://profiles.wordpress.org/mrfoxtalbot/\">Alvaro Gómez</a> · <a href=\"https://profiles.wordpress.org/alh0319/\">Amber Hinds</a> · <a href=\"https://profiles.wordpress.org/aialvi/\">Aminul Islam Alvi</a> · <a href=\"https://profiles.wordpress.org/amitjoel85/\">Amit Joel</a> · <a href=\"https://profiles.wordpress.org/amitraj2203/\">Amit Raj</a> · <a href=\"https://profiles.wordpress.org/amjadr360/\">Amjad Ali</a> · <a href=\"https://profiles.wordpress.org/amykamala/\">Amy Kamala</a> · <a href=\"https://profiles.wordpress.org/anastis/\">Anastis Sourgoutsidis</a> · <a href=\"https://profiles.wordpress.org/anlino/\">Anders Norén</a> · <a href=\"https://profiles.wordpress.org/afercia/\">Andrea Fercia</a> · <a href=\"https://profiles.wordpress.org/andreasdl/\">Andrea Grassi</a> · <a href=\"https://profile